def _build(values):
    if not values or values[0] is None:
        return None
    nodes = [None if v is None else TreeNode(v) for v in values]
    kids = iter(nodes[1:])
    for node in nodes:
        if node is None:
            continue
        node.left = next(kids, None)
        node.right = next(kids, None)
    return nodes[0]


def _serialize(root, limit):
    out, queue, i = [], [root], 0
    while i < len(queue):
        node = queue[i]
        i += 1
        if node is None:
            out.append(None)
            continue
        if len(out) > 2 * limit + 2:
            raise ValueError("returned tree has more nodes than the input (cycle?)")
        out.append(node.val)
        queue.append(node.left)
        queue.append(node.right)
    while out and out[-1] is None:
        out.pop()
    return out


def solve_from_level_order(values: List[Optional[int]], key: int) -> List[Optional[int]]:
    """Test entry point: builds the tree from LeetCode-style level order, calls deleteNode, serializes the result."""
    return _serialize(deleteNode(_build(values), key), len(values))

