def check(args, got):
    values, key = args
    want = sorted(v for v in values if v is not None and v != key)
    if not isinstance(got, list):
        return False
    if not got:
        return want == []
    if got[0] is None:
        return False
    # rebuild children lists from level order
    nodes = [[v, None, None] if v is not None else None for v in got]
    kids = iter(range(1, len(got)))
    for node in nodes:
        if node is None:
            continue
        node[1] = next(kids, None)
        node[2] = next(kids, None)
    seen = []
    stack, cur = [], 0
    while stack or cur is not None:
        while cur is not None and nodes[cur] is not None:
            stack.append(cur)
            cur = nodes[cur][1]
        if not stack:
            break
        idx = stack.pop()
        seen.append(nodes[idx][0])
        cur = nodes[idx][2]
    if len(seen) != sum(1 for v in got if v is not None):
        return False
    return seen == want
